css:
.body {
  background-color: #f8f9fa;
  height: 100%;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: "Inter", sans-serif;
  overflow: hidden;
  perspective: 2000px;
  color: #1a1a1e;
}

.body::before {
  content: "";
  position: absolute;
  width: 140%;
  height: 140%;
  background: radial-gradient(
      circle at 20% 30%,
      rgba(0, 229, 255, 0.08) 0%,
      transparent 40%
    ),
    radial-gradient(
      circle at 80% 70%,
      rgba(112, 0, 255, 0.08) 0%,
      transparent 40%
    );
  animation: nebula-float 20s ease-in-out infinite alternate;
  z-index: -1;
}

@keyframes nebula-float {
  from {
    transform: translate(-10%, -10%) rotate(0deg);
  }
  to {
    transform: translate(5%, 5%) rotate(5deg);
  }
}

.card-frame {
  position: relative;
  width: 360px;
  height: 480px;
  transition: transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
  transform-style: preserve-3d;
}

.card-frame:hover {
  transform: rotateY(10deg) rotateX(5deg) scale(1.02);
}

.laser-border {
  position: absolute;
  inset: -2px;
  border-radius: 32px;
  z-index: 1;
  overflow: hidden;
}

.laser-border::before {
  content: "";
  position: absolute;
  width: 200%;
  height: 200%;
  top: -50%;
  left: -50%;
  background: conic-gradient(
    transparent 70%,
    #00d2ff,
    #9d50bb,
    transparent 90%
  );
  animation: rotate-border 3s linear infinite;
}

.laser-border::after {
  content: "";
  position: absolute;
  inset: 0;
  background: inherit;
  filter: blur(15px);
  opacity: 0.2;
  animation: pulse-glow 4s ease-in-out infinite;
}

.card-body {
  position: relative;
  width: 100%;
  height: 100%;
  background: rgba(255, 255, 255, 0.7);
  border-radius: 30px;
  padding: 30px;
  z-index: 2;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(40px) saturate(200%);
  display: flex;
  flex-direction: column;
  box-shadow: 0 40px 80px -20px rgba(0, 0, 0, 0.08);
}

.header {
  margin-bottom: 50px;
}

.system-tag {
  font-size: 0.6rem;
  text-transform: uppercase;
  letter-spacing: 5px;
  color: #7000ff;
  margin-bottom: 8px;
  display: block;
  font-weight: 700;
}

.main-title {
  font-size: 2.5rem;
  font-weight: 100;
  letter-spacing: -1px;
  line-height: 1;
  color: #000;
}

.main-title b {
  font-weight: 700;
}

.metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 40px;
}

.metric-box {
  border-left: 1px solid rgba(0, 0, 0, 0.05);
  padding-left: 15px;
  position: relative;
}

.metric-box::before {
  content: "";
  position: absolute;
  left: -1px;
  top: 0;
  width: 1px;
  height: 0%;
  background: #00e5ff;
  transition: height 0.5s ease;
}

.card-frame:hover .metric-box::before {
  height: 100%;
}

.metric-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  color: rgba(0, 0, 0, 0.4);
  margin-bottom: 4px;
  display: block;
}

.metric-value {
  font-size: 1.1rem;
  font-weight: 400;
  color: #333;
}

.description {
  font-size: 0.85rem;
  color: rgba(0, 0, 0, 0.6);
  line-height: 1.6;
  font-weight: 400;
  margin-bottom: auto;
}

.btn-container {
  margin-top: 30px;
}

.action-btn {
  width: 100%;
  background: #000;
  border: none;
  color: #fff;
  padding: 18px;
  border-radius: 15px;
  cursor: pointer;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
}

.action-btn:hover {
  letter-spacing: 5px;
  transform: translateY(-2px);
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.2);
}

.grid-overlay {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 0, 0, 0.02) 1px, transparent 1px);
  background-size: 30px 30px;
  pointer-events: none;
  opacity: 1;
}

@keyframes rotate-border {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes pulse-glow {
  0%,
  100% {
    opacity: 0.1;
  }
  50% {
    opacity: 0.3;
  }
}

.sweep {
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.6),
    transparent
  );
  transform: skewX(-25deg);
  transition: 0.8s;
  pointer-events: none;
}

.card-frame:hover .sweep {
  left: 150%;
}
